INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (18, 'Dua jalur jahitan tidak terbentuk dengan benar', 'Salah satu atau kedua jalur jahitan tidak rapi, tidak konsisten, atau hasil jahitan berbeda.', 'Ketegangan kedua benang tidak seimbang, jarum tidak terpasang dengan benar, atau pengaturan pembentukan jahitan perlu diperiksa.', 'Periksa pemasangan kedua benang dan jarum, seimbangkan ketegangan benang, periksa panjang stitch, lalu lakukan uji jahit pada material yang digunakan.', 'Matikan mesin dan lepaskan sumber daya sebelum memeriksa jarum, benang, atau area hook.', 'Data spesifikasi JUKI LH-3528A dan panduan pemeriksaan umum.');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (18, 'Benang salah satu jarum sering putus', 'Benang pada salah satu jalur jahitan putus berulang saat mesin dijalankan.', 'Ketegangan benang terlalu tinggi, jalur benang tidak benar, jarum rusak atau tidak sesuai, atau terdapat bagian kasar pada jalur benang.', 'Periksa jalur benang pada jarum yang bermasalah, sesuaikan ketegangan, ganti jarum bila diperlukan, dan periksa bagian yang bersentuhan dengan benang.', 'Matikan mesin sebelum menyentuh jarum, tension mechanism, atau jalur benang.', 'Data spesifikasi JUKI LH-3528A dan panduan pemeriksaan umum.');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (18, 'Benang bawah sering putus atau tidak stabil', 'Benang bobbin putus, tersangkut, atau salah satu jalur jahitan bawah tidak stabil.', 'Bobbin tidak terpasang dengan benar, ketegangan benang bobbin tidak sesuai, atau salah satu area hook kotor.', 'Periksa pemasangan bobbin, bersihkan area hook, periksa ketegangan benang, dan pastikan kedua hook berputar dengan normal.', 'Matikan mesin sebelum membersihkan area hook dan bobbin.', 'Data spesifikasi JUKI LH-3528A dan panduan pemeriksaan umum.');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (18, 'Salah satu jahitan loncat atau tidak terbentuk', 'Salah satu jalur jahitan memiliki stitch yang hilang atau tidak terbentuk.', 'Jarum bengkok atau tumpul, pemasangan jarum tidak tepat, timing antara jarum dan hook tidak sesuai, atau jalur benang bermasalah.', 'Periksa dan ganti jarum yang bermasalah, pastikan orientasi jarum benar, periksa pemasangan benang, dan lakukan pemeriksaan timing hook oleh teknisi bila diperlukan.', 'Matikan mesin sebelum mengganti jarum atau memeriksa area hook.', 'Data spesifikasi JUKI LH-3528A dan panduan pemeriksaan umum.');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (18, 'Jarak kedua jalur jahitan tidak sesuai needle gauge', 'Jarak antara dua jalur jahitan tidak sesuai dengan ukuran needle gauge yang digunakan.', 'Needle gauge tidak sesuai, posisi jarum tidak tepat, atau komponen needle bar mengalami perubahan posisi.', 'Periksa needle gauge 3,2–6,4 mm sesuai konfigurasi, pastikan kedua jarum terpasang pada posisi yang benar, dan periksa mekanisme needle bar bila jarak tetap tidak sesuai.', 'Matikan mesin sebelum mengubah posisi jarum atau melakukan penyetelan needle gauge.', 'Data spesifikasi JUKI LH-3528A dan panduan pemeriksaan umum.');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (18, 'Panjang kedua jahitan tidak konsisten', 'Panjang stitch pada kedua jalur terlihat tidak seragam atau berubah selama proses jahit.', 'Pengaturan stitch length berubah, mekanisme drop feed tidak bergerak normal, atau tekanan presser foot tidak sesuai.', 'Periksa pengaturan panjang stitch, bersihkan dan periksa feed dog, pastikan drop feed bergerak normal, dan sesuaikan tekanan presser foot sesuai material.', 'Matikan mesin sebelum membersihkan feed dog atau melakukan penyetelan mekanis.', 'Data spesifikasi JUKI LH-3528A dan panduan pemeriksaan umum.');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (18, 'Jarum patah atau posisi kedua jarum tidak normal', 'Salah satu atau kedua jarum bengkok, patah, atau menyentuh presser foot maupun needle plate.', 'Jarum tidak sesuai, pemasangan kurang tepat, needle gauge tidak sesuai, atau terjadi gangguan pada area needle-hook.', 'Ganti jarum dengan ukuran yang sesuai, pasang kedua jarum dengan benar, periksa needle gauge dan posisi presser foot serta needle plate.', 'Matikan mesin dan pastikan pedal tidak aktif sebelum mengganti atau memeriksa jarum.', 'Data spesifikasi JUKI LH-3528A dan panduan pemeriksaan umum.');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (18, 'Pelumasan atau gerakan mesin tidak normal', 'Mesin terdengar kasar, bergerak berat, terlalu panas, atau terdapat indikasi pelumasan tidak normal.', 'Level oli tidak sesuai, sistem pelumasan otomatis tidak bekerja normal, area mekanisme kotor, atau terdapat komponen yang aus.', 'Periksa level dan kondisi oli, pastikan sistem pelumasan bekerja, bersihkan area yang diperlukan, dan hentikan penggunaan untuk pemeriksaan teknisi jika suara atau gerakan tetap tidak normal.', 'Matikan mesin dan lepaskan sumber daya sebelum memeriksa sistem pelumasan atau bagian mekanis yang bergerak.', 'Data spesifikasi JUKI LH-3528A dan panduan pemeriksaan umum.');
